window.PRESENT=(window.PRESENT||[]).concat([
 {week:14, level:"A2", length:"2分", title:"会社とサービスを紹介する",
  skill:"受動態を使って、院と仕事がいつ・どこで始まり、どのように運営されているかを2分で紹介できる。",
  lesson:[
   "第2期の始まりです。ここからプレゼンは2分になります。長くなっても、組み立ては同じです。「導入（あいさつと今日の話）→本論（中身を2〜3つ）→結論（まとめとお礼）」の3つに分けると、聞き手は迷いません。",
   "会社や院を紹介するときは、受動態がとても役に立ちます。「誰がしたか」より「何がどうなっているか」が大事だからです。Our clinic was opened in October 2018.（院は2018年10月に開かれました）、It is run by a small team.（小さなチームで運営されています）のように言います。",
   "本論が2つ以上あるときは、First / Second / Third と番号をつけて話しましょう。聞き手は「今どこの話か」がわかり、安心して聞けます。インドの聞き手にも、番号はとても伝わりやすい合図です。",
   "スライドは「1枚に1つの話」が基本です。院の写真、年と場所、サービスの一覧を、それぞれ別のスライドにします。文字は少なく、話す言葉で説明しましょう。"],
  structure:[{en:"Greeting",ja:"あいさつ"},{en:"Today's topic",ja:"今日の話"},{en:"The clinic",ja:"院の紹介"},{en:"Other work",ja:"ほかの仕事"},{en:"Closing",ja:"まとめとお礼"}],
  phrases:[
   {en:"Let me introduce my clinic and my work.",ja:"私の院と仕事をご紹介します。",note:"導入で今日の話を伝える一言。"},
   {en:"Our clinic was opened in October 2018.",ja:"私たちの院は2018年10月に開かれました。",note:"年や月は was + 過去分詞で。"},
   {en:"It is located near JR Iyo-Ozu Station.",ja:"JR伊予大洲駅の近くにあります。",note:"場所は is located で言うと、ていねい。"},
   {en:"The clinic is run by a small team.",ja:"院は小さなチームで運営されています。",note:"run の過去分詞も run。"},
   {en:"Four main services are offered.",ja:"主なサービスは4つあります。",note:"数を先に言うと、聞き手が準備できる。"},
   {en:"Each treatment is planned for the patient.",ja:"施術は一人ひとりに合わせて計画されます。",note:"ていねいさを伝える文。"},
   {en:"This system is used by our partner clinics.",ja:"このシステムは提携院で使われています。",note:"by ＋ 使う人 で、誰が使うかを言う。"},
   {en:"The shop was founded in 1957.",ja:"その店は1957年に創業しました。",note:"founded は「創業された」。会社の紹介の決まり文句。"},
   {en:"First, … Second, … Third, …",ja:"1つめに…、2つめに…、3つめに…",note:"本論の話を番号で区切る。"},
   {en:"That's a short introduction to who we are.",ja:"以上が、私たちの簡単なご紹介です。",note:"本論を終えて、結論に入る合図。"}],
  model:{title:"院と仕事の紹介", time:"2分", note:"",
   lines:[
    {en:"Good morning, everyone. Thank you for having me today.",ja:"皆さん、おはようございます。本日はお招きいただき、ありがとうございます。"},
    {en:"My name is Akihiro Iwata. Let me introduce my clinic and my work.",ja:"岩田章弘です。私の院と仕事をご紹介します。"},
    {en:"First, the clinic. Aki Acupuncture and Judo Therapy Clinic was opened in October 2018.",ja:"1つめは院です。あき鍼灸整骨院は2018年10月に開院しました。"},
    {en:"It is located in Ozu, a small city in Ehime, near JR Iyo-Ozu Station.",ja:"愛媛県の小さな町、大洲市の、JR伊予大洲駅の近くにあります。"},
    {en:"The clinic is run by a small team. Four staff members work with me.",ja:"院は小さなチームで運営されています。4人のスタッフが私と一緒に働いています。"},
    {en:"Our clinic is visited by people of all ages, from students to older people.",ja:"院には、学生からお年寄りまで、いろいろな年代の方が来られます。"},
    {en:"Four main services are offered: acupuncture, care for injuries and sports injuries, posture and pelvic care, and postnatal care.",ja:"主なサービスは4つです。鍼灸、けがとスポーツのけがのケア、姿勢と骨盤のケア、産後のケアです。"},
    {en:"Each treatment is planned carefully for each patient.",ja:"施術は、一人ひとりに合わせて、ていねいに計画されます。"},
    {en:"Second, my work with other clinics. Sales, patient visits, and the return rate are checked every day at my clinic.",ja:"2つめは、ほかの院との仕事です。私の院では、売上・来院数・再来院率を毎日確かめています。"},
    {en:"From this habit, a booking and customer system was created. It is now used by our partner clinics.",ja:"この習慣から、予約と顧客管理のシステムが作られました。今は提携院で使われています。"},
    {en:"Management advice is also given to these partner clinics.",ja:"提携院には、経営のアドバイスもしています。"},
    {en:"Third, my family business. Odani Sake Ten is a sake shop. It was founded in 1957.",ja:"3つめは、家族の事業です。小谷酒店は酒店で、1957年に創業しました。"},
    {en:"I am in charge of international affairs there.",ja:"私はそこで国際担当をしています。"},
    {en:"That's a short introduction to who we are. In all my work, one idea is kept in mind: give my best to the person in front of me.",ja:"以上が私たちの簡単な紹介です。どの仕事でも、目の前の人に全力を尽くすことを大切にしています。"},
    {en:"Thank you for listening. I'd be happy to answer your questions.",ja:"ご清聴ありがとうございました。ご質問があれば、喜んでお答えします。"}]},
  task:"自分の院と仕事を、受動態を3つ以上使って2分で紹介する。聞き手はインドの取引先。本論は First / Second / Third の3つに分ける。",
  taskEn:"Introduce your clinic and your work to business partners in India in two minutes. Use at least three passive sentences and organize the body into First, Second and Third.",
  qa:[
   {q:"When was your clinic opened?",a:"It was opened in October 2018.",ja:"質問：院はいつ開院しましたか？／答え：2018年10月に開院しました。"},
   {q:"How many people work at your clinic?",a:"The clinic is run by a small team. Four staff members work with me.",ja:"質問：院では何人働いていますか？／答え：小さなチームで運営しています。4人のスタッフが私と一緒に働いています。"}],
  check:["受動態（was opened / is run / is used など）を3つ以上使えたか","be動詞と過去分詞の両方を言えたか（is located の is を落としていないか）","First / Second / Third で本論を区切れたか","2分（約200語）におさまったか","最後にお礼と質問の受付を言えたか"],
  slide:"1枚目は院の写真と「Opened in October 2018 / Ozu, Ehime」だけ。サービスは別のスライドに4つの言葉で並べます。"},

 {week:15, level:"A2", length:"2分", title:"人とサービスをくわしく説明する",
  skill:"関係代名詞 who / which / that を使って、チームとサービスを1文でくわしく説明できる。",
  lesson:[
   "今週は、人やサービスを「くわしく」説明する練習です。関係代名詞を使うと、2つの文を1つにまとめられます。a team who supports patients every day（毎日患者さんを支えるチーム）、a service which helps mothers after birth（出産後のお母さんを助けるサービス）のように、名前のすぐあとに説明をつけます。",
   "ただし、1文に説明を入れすぎると、聞き手はついてこられません。話し言葉では「名前＋説明1つ」で十分です。長くなりそうなら、文を2つに分けましょう。1文は25語までを目安にします。",
   "導入では「今日は人とサービスの2つを話します」と先に予告します。本論では「まず人、次にサービス」の順に話し、結論で「人とサービスは1つにつながっている」とまとめると、話に1本の線が通ります。",
   "スライドでは、サービスごとに「名前」と「短い説明」を1行ずつ並べます。話すときは、その説明を who / which / that でつなげて読み上げるだけで、自然な英語になります。"],
  structure:[{en:"Opening",ja:"あいさつと予告"},{en:"About me",ja:"自分のこと"},{en:"Our team",ja:"チーム"},{en:"Our services",ja:"サービス"},{en:"Closing",ja:"まとめ"}],
  phrases:[
   {en:"Today, I'll talk about two things: our people and our services.",ja:"今日は、人とサービスの2つについてお話しします。",note:"数を先に言う予告。"},
   {en:"I'm a therapist who worked as an athletic trainer.",ja:"私はアスレティックトレーナーとして働いていた施術者です。",note:"自分の経歴を who でつける。"},
   {en:"We are a small team who care about each patient.",ja:"私たちは、患者さん一人ひとりを大切にする小さなチームです。",note:"人には who。"},
   {en:"Acupuncture is a treatment which uses very thin needles.",ja:"鍼は、とても細い針を使う施術です。",note:"物やサービスには which。"},
   {en:"This is a service that helps mothers after giving birth.",ja:"これは、出産後のお母さんを助けるサービスです。",note:"that は人にも物にも使える。"},
   {en:"It's for people who play sports.",ja:"スポーツをする人のためのものです。",note:"対象の人を説明する短い形。"},
   {en:"The system that I built is now used by other clinics.",ja:"私が作ったシステムは、今ほかの院でも使われています。",note:"that I built のように、主語つきの説明もできる。"},
   {en:"These are the partners that we work with in India.",ja:"こちらが、インドで一緒に仕事をしているパートナーです。",note:"work with で終わる形に慣れる。"},
   {en:"What makes us different is our care for each person.",ja:"私たちの違いは、一人ひとりへの心づかいです。",note:"強みを言う決まった形。"},
   {en:"In short, our people and our services are connected.",ja:"まとめると、人とサービスはつながっています。",note:"結論に入る合図。"}],
  model:{title:"私たちのチームとサービス", time:"2分", note:"",
   lines:[
    {en:"Hello, everyone. Thank you for your time today.",ja:"皆さん、こんにちは。今日はお時間をいただき、ありがとうございます。"},
    {en:"Today, I'll talk about two things: our people and our services.",ja:"今日は、人とサービスの2つについてお話しします。"},
    {en:"Let me start with myself. I'm an acupuncturist and judo therapist who has national licenses in Japan.",ja:"まず私のことから。私は日本の国家資格を持つ鍼灸師・柔道整復師です。"},
    {en:"Before I opened my clinic, I was an athletic trainer who worked with high school, university, company and professional teams.",ja:"院を開く前は、高校・大学・実業団・プロのチームで働くアスレティックトレーナーでした。"},
    {en:"Now, our team. We are a small team who care about each patient. Four staff members work with me.",ja:"次にチームです。私たちは、患者さん一人ひとりを大切にする小さなチームです。4人のスタッフが私と一緒に働いています。"},
    {en:"They are people who listen carefully before they touch the body.",ja:"体にふれる前に、まずしっかり話を聞く人たちです。"},
    {en:"Next, our services. Acupuncture is a treatment which uses very thin needles.",ja:"次にサービスです。鍼は、とても細い針を使う施術です。"},
    {en:"We also offer injury care, and sports injury care for people who play sports.",ja:"けがのケアと、スポーツをする人のためのスポーツのけがのケアもしています。"},
    {en:"Posture and pelvic care is a service that helps people with their daily balance.",ja:"姿勢と骨盤のケアは、毎日の体のバランスを整えるサービスです。"},
    {en:"Postnatal care is a service that helps mothers after giving birth.",ja:"産後のケアは、出産後のお母さんを助けるサービスです。"},
    {en:"There is one more thing which I want to share. I check our numbers every day, so I built a booking and customer system.",ja:"もう1つお伝えしたいことがあります。私は毎日数字を確かめているので、予約と顧客管理のシステムを作りました。"},
    {en:"The system that I built is now used by our partner clinics.",ja:"私が作ったシステムは、今は提携院で使われています。"},
    {en:"I also give management advice to the clinics that use it.",ja:"それを使う院には、経営のアドバイスもしています。"},
    {en:"What makes us different is our care for each person.",ja:"私たちの違いは、一人ひとりへの心づかいです。"},
    {en:"In short, our people and our services are connected. Good people make good services.",ja:"まとめると、人とサービスはつながっています。良い人が良いサービスを作ります。"},
    {en:"Thank you very much. Please feel free to ask me anything.",ja:"ありがとうございました。どうぞ何でも聞いてください。"}]},
  task:"自分のチームとサービスを、関係代名詞を4つ以上使って2分で説明する。聞き手は院の見学に来たインドのクリニックの方。",
  taskEn:"Describe your team and services to visitors from a clinic in India in two minutes. Use who, which or that at least four times.",
  qa:[
   {q:"What kind of patients come to your clinic?",a:"We see many people who have back pain, and people who play sports.",ja:"質問：どんな患者さんが来ますか？／答え：腰の痛みがある方や、スポーツをする方が多く来られます。"},
   {q:"Can other clinics use your system?",a:"Yes. The system that I built is used by our partner clinics.",ja:"質問：ほかの院もシステムを使えますか？／答え：はい。私が作ったシステムは提携院で使われています。"}],
  check:["人には who、物やサービスには which / that を使い分けたか","1文に説明を入れすぎず、25語以内にしたか","導入で「2つの話をします」と予告できたか","結論で「人とサービスのつながり」をまとめられたか","2分（約210語）で話せたか"],
  slide:"サービスのスライドは「名前＋短い説明」を4行。例：Acupuncture — thin needles。話すときに which でつなげます。"},

 {week:16, level:"A2", length:"2分", title:"院の案内と1日の流れを説明する",
  skill:"where / when / what を使って、場所の案内と1日の流れを、順番どおりに説明できる。",
  lesson:[
   "今週は「場所」と「時間の流れ」を説明します。場所には where（the city where I opened my clinic ＝私が院を開いた町）、時には when（the time when I check the numbers ＝数字を確かめる時間）、「〜なこと」には what（What patients want most is… ＝患者さんが一番望むことは…）を使います。",
   "流れを説明するときは、聞き手の頭の中に「地図」や「時計」を作ってあげることが大切です。First / Then / After that / Finally のような順番の言葉を使い、時間の順に話しましょう。順番が前後すると、聞き手は迷ってしまいます。",
   "What で始まる文（What I do first is… ／ What I check every evening is…）は、大事なことを最後に置けるので、聞き手の注意を集めるのに便利です。1回のプレゼンで2〜3回使うと、話にメリハリが出ます。",
   "スライドは、左から右へ進む矢印や、時計の図で「流れ」を見せます。文字は「受付→お話→施術→アドバイス」のように短い言葉だけにして、くわしいことは話して伝えましょう。"],
  structure:[{en:"Opening",ja:"あいさつ"},{en:"Where we are",ja:"院の場所"},{en:"A patient's visit",ja:"来院の流れ"},{en:"My day",ja:"私の1日"},{en:"Closing",ja:"まとめ"}],
  phrases:[
   {en:"Ozu is the city where I opened my clinic.",ja:"大洲は、私が院を開いた町です。",note:"場所の説明は where。"},
   {en:"This is the room where we do treatments.",ja:"ここが施術をする部屋です。",note:"写真を見せながら言う。"},
   {en:"Let me walk you through a typical visit.",ja:"ふつうの来院の流れをご案内します。",note:"walk you through ＝順に案内する。"},
   {en:"First, … Then, … After that, … Finally, …",ja:"まず…、次に…、そのあと…、最後に…",note:"流れを話す4つの言葉。"},
   {en:"The first visit is the time when we listen the most.",ja:"初めての来院は、一番よく話を聞く時間です。",note:"時の説明は when。"},
   {en:"What patients want most is to feel better and understand why.",ja:"患者さんが一番望むのは、楽になって、その理由がわかることです。",note:"What で始めて、大事なことを最後に。"},
   {en:"What I check every evening is our sales, visits and return rate.",ja:"毎晩確かめるのは、売上・来院数・再来院率です。",note:"自分の習慣を伝える。"},
   {en:"Evening is the time when I look back on the day.",ja:"夕方は、1日をふりかえる時間です。",note:"when の練習。"},
   {en:"Please let me know when you would like to visit.",ja:"いつ来られたいか、教えてください。",note:"案内のあとに相手の都合を聞く。when のあとは 主語＋動詞。"},
   {en:"That's the flow of a day at our clinic.",ja:"以上が、院の1日の流れです。",note:"まとめの合図。"}],
  model:{title:"院の案内と1日の流れ", time:"2分", note:"時間や来院の流れは例です。自分の院に合わせて入れかえましょう。",
   lines:[
    {en:"Hello, everyone. Today, I'll show you around my clinic and explain a day there.",ja:"皆さん、こんにちは。今日は院をご案内して、院の1日をご説明します。"},
    {en:"Ozu is the city where I opened my clinic in October 2018.",ja:"大洲は、私が2018年10月に院を開いた町です。"},
    {en:"It is a small city in Ehime. The clinic is near JR Iyo-Ozu Station, where many people pass every day.",ja:"愛媛県の小さな町です。院はJR伊予大洲駅の近くにあり、毎日たくさんの人が通ります。"},
    {en:"Now, let me walk you through a typical visit.",ja:"では、ふつうの来院の流れをご案内します。"},
    {en:"First, the patient comes to the reception, where our staff welcome them.",ja:"まず、患者さんは受付に来られ、スタッフがお迎えします。"},
    {en:"Then, we sit down and talk. The first visit is the time when we listen the most.",ja:"次に、座ってお話しします。初めての来院は、一番よく話を聞く時間です。"},
    {en:"We ask where it hurts, when it started, and what they want to do again.",ja:"どこが痛いか、いつ始まったか、何をまたしたいかをうかがいます。"},
    {en:"After that, we move to the treatment room, where we do acupuncture or other care.",ja:"そのあと施術室に移り、鍼やほかのケアを行います。"},
    {en:"Finally, we explain what we found and what they can do at home.",ja:"最後に、わかったことと、家でできることを説明します。"},
    {en:"What patients want most is to feel better and understand why.",ja:"患者さんが一番望むのは、楽になって、その理由がわかることです。"},
    {en:"Next, my own day. In the morning, I prepare the rooms with my team.",ja:"次に、私自身の1日です。朝は、チームと一緒に部屋の準備をします。"},
    {en:"During the day, I treat patients and help my staff.",ja:"日中は、患者さんを施術し、スタッフを手伝います。"},
    {en:"Evening is the time when I look back on the day.",ja:"夕方は、1日をふりかえる時間です。"},
    {en:"What I check every evening is our sales, visits and return rate.",ja:"毎晩確かめるのは、売上・来院数・再来院率です。"},
    {en:"These numbers tell me what went well and what we should change.",ja:"この数字が、何がうまくいき、何を変えるべきかを教えてくれます。"},
    {en:"That's the flow of a day at our clinic. Thank you for listening.",ja:"以上が、院の1日の流れです。ご清聴ありがとうございました。"}]},
  task:"自分の院の場所と、患者さんの来院の流れ、自分の1日を、where / when / what を使って2分で説明する。聞き手は院を訪ねる予定のインドのパートナー。",
  taskEn:"Explain where your clinic is, the flow of a patient's visit, and your own day to a partner from India who plans to visit. Use where, when and what. Speak for two minutes.",
  qa:[
   {q:"How do I get to your clinic from the station?",a:"It's near JR Iyo-Ozu Station. I'll send you a map, so it will be easy to find.",ja:"質問：駅から院へはどう行けばいいですか？／答え：JR伊予大洲駅の近くです。地図をお送りしますので、すぐわかります。"},
   {q:"What do you do on the first visit?",a:"The first visit is the time when we listen the most. We ask where it hurts and when it started.",ja:"質問：初めての来院では何をしますか？／答え：初回は一番よく話を聞く時間です。どこが痛いか、いつ始まったかをうかがいます。"}],
  check:["場所に where、時に when を正しく使えたか","What で始まる文を2つ以上使えたか","First / Then / After that / Finally の順に話せたか","来院の流れと自分の1日を分けて話せたか","2分（約220語）におさまったか"],
  slide:"受付→お話→施術→アドバイスを、左から右への矢印4つで見せます。1つの箱に言葉は1つだけにしましょう。"},

 {week:17, level:"A2", length:"2分", title:"資料と商品を見せる",
  skill:"分詞（the chart shown here / a growing number）を使って、グラフや画面を見せながら説明できる。",
  lesson:[
   "今週は、スライドの資料やグラフを「見せながら話す」練習です。分詞を使うと、名前に説明を短くつけられます。the chart shown here（ここに示したグラフ）、a screen showing today's bookings（今日の予約を表示している画面）、a growing number of patients（増えている患者さんの数）のように言います。",
   "グラフを見せるときは、3つの順番で話します。①何のグラフか（This chart shows…）、②一番大事な点（As you can see, …）、③それが何を意味するか（This means…）。この順番を守ると、聞き手はグラフの見方に迷いません。",
   "大事なのは、聞き手に「どこを見ればいいか」を言葉で教えることです。Please look at the blue line.（青い線を見てください）、On the left, you can see…（左側に…が見えます）のように、目を案内してから説明しましょう。",
   "スライドのグラフは1枚に1つ。線や棒は2本までにして、大事な数字だけを大きく書きます。タイトルには「何がわかるか」を書くと、見ただけで伝わります。"],
  structure:[{en:"Opening",ja:"あいさつと目的"},{en:"The system",ja:"システムの紹介"},{en:"The chart",ja:"グラフの説明"},{en:"What it means",ja:"意味"},{en:"Closing",ja:"まとめ"}],
  phrases:[
   {en:"Please take a look at the chart shown here.",ja:"ここに示したグラフをご覧ください。",note:"shown here ＝ここに示された。"},
   {en:"This chart shows our return rate over six months.",ja:"このグラフは6か月間の再来院率を示しています。",note:"①何のグラフかを言う。"},
   {en:"As you can see, the line is going up.",ja:"ご覧のとおり、線は上がっています。",note:"②一番大事な点。"},
   {en:"This means more patients are coming back.",ja:"これは、もどって来る患者さんが増えているということです。",note:"③意味を言う。"},
   {en:"Here is a screen showing today's bookings.",ja:"こちらは、今日の予約を表示している画面です。",note:"現在分詞 showing で説明。"},
   {en:"Please look at the blue line on the left.",ja:"左側の青い線を見てください。",note:"聞き手の目を案内する。"},
   {en:"There is a growing number of patients in their twenties.",ja:"20代の患者さんが増えています。",note:"growing ＝増えている。"},
   {en:"This is a report printed every evening.",ja:"これは毎晩印刷される報告書です。",note:"過去分詞 printed で説明。"},
   {en:"The numbers used here are only examples.",ja:"ここで使っている数字は例です。",note:"例の数字だと正直に伝える。"},
   {en:"The key point is simple: check the numbers every day.",ja:"大事な点は簡単です。毎日数字を確かめることです。",note:"結論を一言で。"}],
  model:{title:"予約・顧客管理システムの画面とグラフ", time:"2分", note:"数字は練習用の例です。自分の数字に入れかえましょう。",
   lines:[
    {en:"Good afternoon, everyone. Today, I'd like to show you the system used at our clinic.",ja:"皆さん、こんにちは。今日は、私たちの院で使っているシステムをお見せします。"},
    {en:"It is a booking and customer system made for small clinics.",ja:"小さな院のために作られた、予約と顧客管理のシステムです。"},
    {en:"I built it because I check our sales, visits and return rate every day.",ja:"私は毎日、売上・来院数・再来院率を確かめているので、これを作りました。"},
    {en:"First, here is a screen showing today's bookings.",ja:"まず、こちらは今日の予約を表示している画面です。"},
    {en:"On the left, you can see the names and times. On the right, you can see notes written by the staff.",ja:"左側には名前と時間が見えます。右側には、スタッフが書いたメモが見えます。"},
    {en:"These notes help us remember what each patient told us last time.",ja:"このメモのおかげで、それぞれの患者さんが前回話したことを覚えておけます。"},
    {en:"Next, please take a look at the chart shown here.",ja:"次に、ここに示したグラフをご覧ください。"},
    {en:"This chart shows the return rate at one clinic over six months.",ja:"このグラフは、ある院の6か月間の再来院率を示しています。"},
    {en:"Please look at the blue line. In the first month, the rate was 60 percent.",ja:"青い線を見てください。最初の月、再来院率は60パーセントでした。"},
    {en:"As you can see, the line is going up. In the sixth month, it reached 72 percent.",ja:"ご覧のとおり、線は上がっています。6か月目には72パーセントになりました。"},
    {en:"This means more patients are coming back for their next visit.",ja:"これは、次の来院にもどって来る患者さんが増えているということです。"},
    {en:"We also saw a growing number of patients booking their next visit before they left.",ja:"帰る前に次の予約を入れる患者さんも増えていました。"},
    {en:"Finally, this is a short report printed every evening. It shows the numbers of the day on one page.",ja:"最後に、これは毎晩印刷される短い報告書です。その日の数字を1ページで見せます。"},
    {en:"The numbers used here are only examples, but the idea is real.",ja:"ここで使っている数字は例ですが、考え方は本物です。"},
    {en:"The key point is simple: check the numbers every day, and act on them.",ja:"大事な点は簡単です。毎日数字を確かめて、それをもとに動くことです。"},
    {en:"Thank you for your attention. I'm happy to show you more.",ja:"ご清聴ありがとうございました。もっとお見せできますので、どうぞ。"}]},
  task:"自分のシステムの画面と、例の数字で作ったグラフ1枚を見せながら、分詞を3つ以上使って2分で説明する。聞き手は提携を考えている院の院長。",
  taskEn:"Show a screen of your system and one chart with example numbers to a clinic owner who is thinking about a partnership. Use at least three participles, like shown here or showing. Speak for two minutes.",
  qa:[
   {q:"Why did the return rate go up?",a:"I think the notes written by the staff helped. Patients felt we remembered them.",ja:"質問：なぜ再来院率が上がったのですか？／答え：スタッフが書いたメモが役に立ったと思います。患者さんが「覚えてもらえている」と感じたからです。"},
   {q:"Can I see the evening report?",a:"Of course. Here is a report printed yesterday. It shows the numbers of the day on one page.",ja:"質問：毎晩の報告書を見られますか？／答え：もちろんです。こちらが昨日印刷した報告書です。その日の数字を1ページで見せます。"}],
  check:["分詞（shown here / showing / growing / printed など）を3つ以上使えたか","グラフを「何のグラフか→大事な点→意味」の順に説明できたか","「左側」「青い線」など、聞き手の目を案内できたか","例の数字は例だと伝えたか","2分（約230語）で話せたか"],
  slide:"グラフのタイトルを「Return rate is going up」のように、わかることにします。線は1本、最初と最後の数字だけを大きく書きます。"},

 {week:18, level:"A2-B1", length:"2分", title:"理由と条件で話をつなぐ",
  skill:"because / if / although / so を使って、理由と条件のある話を、筋道を立てて伝えられる。",
  lesson:[
   "今週は、文と文を「つなぐ」練習です。because（なぜなら）、so（だから）、if（もし〜なら）、although（〜だけれど）の4つを使うと、話に筋道ができます。聞き手は「なぜそう言えるのか」がわかるので、話を信じやすくなります。",
   "ビジネスのプレゼンでは「主張→理由→例→もう一度主張」の順がよく使われます。I believe… because… For example… So… のように話すと、短い時間でも説得力が出ます。今週の手本もこの順番で作っています。",
   "although は、反対の意見や心配を先に受け止めるときに使います。Although it takes time, it saves time later.（時間はかかりますが、あとで時間の節約になります）のように言うと、聞き手の「でも…」という気持ちに先に答えられます。",
   "スライドには、主張を1行、理由を3つまで書きます。理由には番号をつけ、話すときも First reason… と番号で言いましょう。"],
  structure:[{en:"Opening",ja:"あいさつ"},{en:"Main point",ja:"主張"},{en:"Reasons",ja:"理由"},{en:"Condition",ja:"条件"},{en:"Closing",ja:"もう一度主張"}],
  phrases:[
   {en:"I believe that … because …",ja:"私は…と考えます。なぜなら…",note:"主張と理由を1文で。"},
   {en:"There are three reasons for this.",ja:"これには理由が3つあります。",note:"理由の数を先に言う。"},
   {en:"The first reason is that …",ja:"1つめの理由は…です。",note:"番号つきの理由。"},
   {en:"If you check the numbers every day, you can act quickly.",ja:"毎日数字を確かめれば、すぐに動けます。",note:"if ＋ 現在形で条件。"},
   {en:"Although it takes time, it saves time later.",ja:"時間はかかりますが、あとで時間の節約になります。",note:"心配を先に受け止める。"},
   {en:"So, my point is this: …",ja:"ですから、私が言いたいのはこういうことです。",note:"結論に入る合図。"},
   {en:"For example, …",ja:"たとえば、…",note:"理由のあとに例を1つ。"},
   {en:"This is important because small changes become big changes.",ja:"小さな変化が大きな変化になるので、これは大切です。",note:"because で理由をつける。"},
   {en:"If you have any doubts, please tell me.",ja:"もし疑問があれば、教えてください。",note:"聞き手への声かけ。"},
   {en:"That's why I recommend a daily check.",ja:"だから、毎日の確認をおすすめします。",note:"That's why ＝だから。"}],
  model:{title:"毎日数字を見ることをすすめる理由", time:"2分", note:"",
   lines:[
    {en:"Hello, everyone. Thank you for coming.",ja:"皆さん、こんにちは。お越しいただき、ありがとうございます。"},
    {en:"Today, I want to share one simple idea. I believe that clinic owners should check their numbers every day.",ja:"今日は、1つの簡単な考えをお伝えします。院長は毎日数字を確かめるべきだと、私は考えています。"},
    {en:"There are three reasons for this.",ja:"これには理由が3つあります。"},
    {en:"The first reason is that problems are small at the start.",ja:"1つめの理由は、問題は最初は小さいということです。"},
    {en:"If you check the numbers every day, you can find a problem while it is still small.",ja:"毎日数字を確かめれば、問題がまだ小さいうちに見つけられます。"},
    {en:"For example, if the return rate goes down for a few days, you can ask your staff why.",ja:"たとえば、再来院率が数日下がったら、スタッフに理由を聞くことができます。"},
    {en:"The second reason is that your staff learn too. When they see the numbers, they understand their work better.",ja:"2つめの理由は、スタッフも学ぶということです。数字を見ると、自分の仕事がよりよくわかります。"},
    {en:"The third reason is about the patients. Our numbers are really about people, so they help us care for each person.",ja:"3つめの理由は、患者さんのことです。数字は本当は人のことなので、一人ひとりを大切にする助けになります。"},
    {en:"Now, some of you may think this is too much work.",ja:"さて、これは手間がかかりすぎると思う方もいるかもしれません。"},
    {en:"Although it takes time at first, it saves time later.",ja:"最初は時間がかかりますが、あとで時間の節約になります。"},
    {en:"I check our sales, visits and return rate every day, so I built a simple system for it.",ja:"私は毎日、売上・来院数・再来院率を確かめているので、そのための簡単なシステムを作りました。"},
    {en:"Because the system does the counting, the daily check takes only a few minutes.",ja:"システムが数えてくれるので、毎日の確認は数分で終わります。"},
    {en:"Our partner clinics use the same system, so they can do the same check.",ja:"提携院も同じシステムを使っているので、同じ確認ができます。"},
    {en:"So, my point is this: small checks every day lead to big changes.",ja:"ですから、私が言いたいのはこういうことです。毎日の小さな確認が、大きな変化につながります。"},
    {en:"That's why I recommend a daily check to every clinic owner.",ja:"だから、すべての院長に毎日の確認をおすすめします。"},
    {en:"If you have any doubts, please tell me. Thank you.",ja:"もし疑問があれば、教えてください。ありがとうございました。"}]},
  task:"「毎日数字を見ることをすすめる理由」か、自分で選んだ主張を1つ決め、because / if / although / so を全部使って2分で話す。聞き手は提携院の院長たち。",
  taskEn:"Choose one main point, such as why clinic owners should check their numbers every day. Give three reasons and use because, if, although and so. Speak to partner clinic owners for two minutes.",
  qa:[
   {q:"What if I don't have time every day?",a:"Although it takes time at first, it gets faster. If you use a simple system, it takes only a few minutes.",ja:"質問：毎日時間がない場合は？／答え：最初は時間がかかりますが、だんだん早くなります。簡単なシステムを使えば、数分で終わります。"},
   {q:"Which number is the most important?",a:"I think the return rate is, because it shows if patients trust us.",ja:"質問：どの数字が一番大事ですか？／答え：再来院率だと思います。患者さんが信頼してくれているかがわかるからです。"}],
  check:["because / if / although / so を全部使えたか","「主張→理由3つ→例→もう一度主張」の順になっていたか","理由に番号をつけて話せたか","although で聞き手の心配に先に答えられたか","2分（約240語）で話せたか"],
  slide:"上に主張を1行（Check your numbers every day）、下に理由を3つ、番号つきで短く書きます。"},

 {week:19, level:"B1", length:"2分", title:"ていねいに呼びかけ、質問を受ける入門",
  skill:"間接疑問（Could you tell me what…? / Let me know if…）を使って、聞き手に呼びかけ、質問を受けて答えられる。",
  lesson:[
   "プレゼンは、話して終わりではありません。聞き手に問いかけたり、質問を受けたりして、はじめて「会話」になります。今週は、そのためのていねいな言い方を学びます。",
   "間接疑問は、質問を文の中に入れる言い方です。What do you need? と聞くより、Could you tell me what you need?（何が必要か教えていただけますか）の方がずっとやわらかく聞こえます。疑問文の部分は「主語＋動詞」の順になる（what you need）ことに気をつけましょう。",
   "質問を受けるときの流れは「お礼→確認→答え→確かめ」です。That's a good question.（よい質問です）とお礼を言い、Let me check if I understand.（理解が合っているか確かめさせてください）と確認し、答えたあとで Does that answer your question?（お答えになっていますか）と聞きます。答えがわからないときは、正直に「確かめて後でお知らせします」と言えば大丈夫です。",
   "スライドの最後に「Questions?」の1枚を用意しておきましょう。また、話の途中で聞き手に問いかけるときは、スライドに問いを1行だけ大きく出すと、考える時間が生まれます。"],
  structure:[{en:"Opening",ja:"あいさつ"},{en:"A question to the audience",ja:"聞き手への問いかけ"},{en:"Our service",ja:"サービスの説明"},{en:"Inviting questions",ja:"質問の受付"},{en:"Answering",ja:"答える"}],
  phrases:[
   {en:"Could you tell me what kind of guests you usually welcome?",ja:"ふだん、どんなお客様をお迎えしているか教えていただけますか？",note:"what ＋ 主語 ＋ 動詞 の順。"},
   {en:"Let me know if anything is unclear.",ja:"わかりにくいところがあれば、教えてください。",note:"話の途中で使う声かけ。"},
   {en:"May I ask how many Japanese guests you have?",ja:"日本人のお客様がどのくらいいらっしゃるか、うかがってもいいですか？",note:"how many ＋ 名詞 ＋ 主語 ＋ 動詞。"},
   {en:"I'd like to know what you find most difficult.",ja:"何が一番むずかしいと感じているか、知りたいです。",note:"I'd like to know でやわらかく。"},
   {en:"Now, I'd be happy to take your questions.",ja:"では、喜んでご質問をお受けします。",note:"質疑応答に入る合図。"},
   {en:"That's a good question. Thank you.",ja:"よいご質問です。ありがとうございます。",note:"まずお礼。考える時間にもなる。"},
   {en:"Let me check if I understand your question.",ja:"ご質問を正しく理解しているか確かめさせてください。",note:"if ＝〜かどうか。"},
   {en:"Could you tell me what you mean by that?",ja:"それはどういう意味か、教えていただけますか？",note:"聞き取れなかったとき。"},
   {en:"I'm not sure, but I'll find out and let you know.",ja:"わかりませんが、調べてお知らせします。",note:"わからないときは正直に。"},
   {en:"Does that answer your question?",ja:"お答えになっていますか？",note:"答えのあとの確かめ。"}],
  model:{title:"インドのホテルへのおもてなしの紹介と質疑", time:"2分", note:"",
   lines:[
    {en:"Good morning, everyone. Thank you for inviting me to your hotel.",ja:"皆さん、おはようございます。ホテルにお招きいただき、ありがとうございます。"},
    {en:"Before I start, may I ask you something? Could you tell me what kind of guests you usually welcome?",ja:"始める前に、1つうかがってもいいですか？ふだん、どんなお客様をお迎えしているか教えていただけますか？"},
    {en:"Thank you. I'd also like to know if you welcome Japanese guests.",ja:"ありがとうございます。日本人のお客様をお迎えしているかどうかも知りたいです。"},
    {en:"I see. That's very helpful.",ja:"なるほど。とても参考になります。"},
    {en:"Today, I'll talk about omotenashi, the Japanese way of welcoming people.",ja:"今日は、人を迎える日本のやり方、おもてなしについてお話しします。"},
    {en:"I help hotels, restaurants and clinics in India welcome Japanese guests, and Indian guests who love Japan.",ja:"私は、インドのホテルやレストラン、クリニックが、日本人のお客様や日本好きのインドのお客様を迎えるお手伝いをしています。"},
    {en:"For example, a Japanese guest may be tired after a long flight, but they may not say so.",ja:"たとえば、日本人のお客様は長いフライトで疲れていても、そう言わないことがあります。"},
    {en:"A good host notices this and offers tea or a quiet room.",ja:"よいおもてなしをする人は、それに気づいて、お茶や静かな部屋をすすめます。"},
    {en:"Omotenashi is not only about a polite bow. It means thinking about what the guest needs before they ask.",ja:"おもてなしは、ていねいなおじぎだけではありません。お客様が頼む前に、何が必要かを考えることです。"},
    {en:"At my clinic in Japan, we always ask ourselves how the patient feels today.",ja:"日本の私の院では、いつも「この患者さんは今日どんな気分だろう」と考えています。"},
    {en:"The same idea works for hotels. Let me know if anything is unclear so far.",ja:"同じ考えがホテルでも使えます。ここまでで、わかりにくいところがあれば教えてください。"},
    {en:"Now, I'd be happy to take your questions.",ja:"では、喜んでご質問をお受けします。"},
    {en:"Yes, please. … That's a good question. Thank you.",ja:"はい、どうぞ。…よいご質問です。ありがとうございます。"},
    {en:"Let me check if I understand. You'd like to know how long the training takes. Is that right?",ja:"理解が合っているか確かめさせてください。研修にどのくらい時間がかかるか知りたい、ということですね？"},
    {en:"It depends on your team. Could you tell me how many staff members will join?",ja:"チームによって変わります。何人のスタッフが参加するか教えていただけますか？"},
    {en:"Thank you. Then I'll make a plan for your team and send it to you.",ja:"ありがとうございます。では、チームに合わせた計画を作ってお送りします。"},
    {en:"If you'd like, I can also tell you what other hotels usually choose.",ja:"よろしければ、ほかのホテルがふだん何を選ぶかもお伝えできます。"},
    {en:"Does that answer your question?",ja:"お答えになっていますか？"},
    {en:"Good. Are there any other questions? If you think of one later, please let me know by email.",ja:"よかったです。ほかにご質問はありますか？あとで思いついたら、メールでお知らせください。"},
    {en:"Thank you very much for your time today.",ja:"今日はお時間をいただき、本当にありがとうございました。"}]},
  task:"インドのホテルの方に、おもてなしのお手伝いを1分で紹介し、そのあと1分で質問を受けて答える。間接疑問を4つ以上使う。",
  taskEn:"Introduce your omotenashi support to a hotel team in India for one minute. Then take questions for one minute. Use at least four indirect questions, like Could you tell me what…?",
  qa:[
   {q:"Can you tell me what omotenashi means?",a:"Sure. It means thinking about what the guest needs before they ask.",ja:"質問：おもてなしとは何か教えてもらえますか？／答え：はい。お客様が頼む前に、何が必要かを考えることです。"},
   {q:"Do you know how much the training costs?",a:"That's a good question. It depends on the size of your team. I'll find out and let you know.",ja:"質問：研修の費用はわかりますか？／答え：よいご質問です。チームの大きさによって変わります。確かめてお知らせします。"},
   {q:"Could you explain what you do at your clinic?",a:"Of course. I run a clinic in Ozu, Ehime. We offer acupuncture and care for injuries.",ja:"質問：院で何をしているか説明していただけますか？／答え：もちろんです。愛媛県大洲市で院を営んでいます。鍼灸とけがのケアをしています。"}],
  check:["間接疑問で「主語＋動詞」の順（what you need）にできたか","話の初めに聞き手へ問いかけられたか","質問に「お礼→確認→答え→確かめ」の順で答えられたか","わからない質問に正直に答えられたか","2分（約250語）で話せたか"],
  slide:"最初のスライドに問いを1行（What kind of guests do you welcome?）、最後に「Questions?」の1枚を用意します。"},

 {week:20, level:"B1", length:"2分30秒", title:"これまでの歩みをタイムラインで語る",
  skill:"現在完了進行形と過去完了を使って、自分の歩みを時間の順に、つながりのある話として語れる。",
  lesson:[
   "今週は、自分の「これまで」を時間の順に話す練習です。聞き手は、あなたがどんな道を歩いてきたかを知ると、あなたの今の仕事を信頼しやすくなります。",
   "今も続いていることは現在完了進行形で言います。I have been running my clinic since 2018.（2018年から院を営んでいます）。過去のある時より前のことは過去完了で言います。Before I opened my clinic, I had worked as an athletic trainer.（院を開く前、アスレティックトレーナーとして働いていました）。この2つで、時間の「前と後」がはっきりします。",
   "タイムラインの話は、年や出来事を並べるだけでは退屈です。それぞれの出来事に「そこで何を学んだか」「それが今にどうつながるか」を一言そえましょう。最後に「だから今、こうしています」と今につなげると、結論がはっきりします。",
   "スライドは、横に1本の線を引き、左から右へ出来事を3〜5個置きます。年は大きく、説明は短く。今話している出来事だけ色を変えると、聞き手は話について来られます。"],
  structure:[{en:"Opening",ja:"あいさつ"},{en:"Before the clinic",ja:"院を開く前"},{en:"Opening the clinic",ja:"開院"},{en:"New work",ja:"広がった仕事"},{en:"Now and next",ja:"今とこれから"}],
  phrases:[
   {en:"Let me tell you how I got here.",ja:"ここまでの歩みをお話しします。",note:"タイムラインの導入。"},
   {en:"Before I opened my clinic, I had worked as an athletic trainer.",ja:"院を開く前は、アスレティックトレーナーとして働いていました。",note:"過去完了で「もっと前」。"},
   {en:"By then, I had learned a lot about the body.",ja:"そのころまでに、体について多くを学んでいました。",note:"By then ＝そのときまでに。"},
   {en:"I have been running my clinic since October 2018.",ja:"2018年10月から院を営んでいます。",note:"今も続いていること。"},
   {en:"I have been checking our numbers every day.",ja:"毎日数字を確かめ続けています。",note:"習慣が続いていることを強く言う。"},
   {en:"I have been visiting India regularly.",ja:"インドを定期的に訪れています。",note:"regularly ＝定期的に。"},
   {en:"This experience led me to my next step.",ja:"この経験が、次の一歩につながりました。",note:"出来事をつなぐ言い方。"},
   {en:"Looking back, each step was connected.",ja:"ふりかえると、一つひとつの歩みがつながっていました。",note:"まとめに使う。"},
   {en:"The shop has been serving customers since 1957.",ja:"その店は1957年からお客様にサービスしています。",note:"会社の歴史の言い方。"},
   {en:"And that brings us to today.",ja:"そして、今日に至ります。",note:"タイムラインを今につなぐ合図。"}],
  model:{title:"私の歩み", time:"2分30秒", note:"",
   lines:[
    {en:"Good afternoon, everyone. Let me tell you how I got here.",ja:"皆さん、こんにちは。ここまでの歩みをお話しします。"},
    {en:"I was born in Yokohama. Today, I live and work in Ozu, a small city in Ehime.",ja:"私は横浜で生まれました。今は、愛媛県の小さな町、大洲で暮らし、働いています。"},
    {en:"Before I opened my clinic, I had worked as an athletic trainer.",ja:"院を開く前は、アスレティックトレーナーとして働いていました。"},
    {en:"I had supported high school, university, company and professional sports teams.",ja:"高校・大学・実業団・プロのスポーツチームを支えていました。"},
    {en:"By then, I had also become a licensed acupuncturist and judo therapist.",ja:"そのころまでに、鍼灸師と柔道整復師の資格も取っていました。"},
    {en:"Working with athletes taught me one thing: listen carefully, and give your best to the person in front of you.",ja:"選手たちと働いて、1つのことを学びました。よく聞くこと、そして目の前の人に全力を尽くすことです。"},
    {en:"This experience led me to my next step. In October 2018, I opened Aki Acupuncture and Judo Therapy Clinic.",ja:"この経験が次の一歩につながりました。2018年10月、あき鍼灸整骨院を開きました。"},
    {en:"I have been running the clinic since then, with four staff members today.",ja:"それ以来、院を営んでいます。今は4人のスタッフがいます。"},
    {en:"From the start, I have been checking our sales, visits and return rate every day.",ja:"開院のときから、売上・来院数・再来院率を毎日確かめ続けています。"},
    {en:"Because I had been doing this for a long time, I decided to build a booking and customer system.",ja:"長い間これを続けていたので、予約と顧客管理のシステムを作ることにしました。"},
    {en:"Now our partner clinics use it, and I have been giving them management advice.",ja:"今は提携院がそれを使っていて、私は経営のアドバイスを続けています。"},
    {en:"There is another part of my story. My family runs Odani Sake Ten, a sake shop.",ja:"私の話には、もう1つの部分があります。家族が小谷酒店という酒店を営んでいます。"},
    {en:"The shop has been serving customers since 1957. I work there as the International Affairs Manager.",ja:"店は1957年からお客様にサービスしています。私はそこで国際担当をしています。"},
    {en:"I have also been visiting India regularly, and working with partners there.",ja:"インドも定期的に訪れ、現地のパートナーと仕事をしています。"},
    {en:"I help hotels, restaurants and clinics welcome guests with real omotenashi.",ja:"ホテルやレストラン、クリニックが、本物のおもてなしでお客様を迎えるお手伝いをしています。"},
    {en:"Many of these ideas came from what I had learned at the clinic.",ja:"その考えの多くは、院で学んでいたことから生まれました。"},
    {en:"And to do this work better, I have been studying English every day.",ja:"そして、この仕事をもっとよくするために、毎日英語を勉強しています。"},
    {en:"Looking back, each step was connected. Sports led to the clinic, and the clinic led to India.",ja:"ふりかえると、一つひとつの歩みがつながっていました。スポーツが院へ、院がインドへとつながりました。"},
    {en:"And that brings us to today. Thank you for listening.",ja:"そして、今日に至ります。ご清聴ありがとうございました。"}]},
  task:"自分の歩みを、出来事4つ以上のタイムラインにして2分30秒で話す。現在完了進行形を3つ以上、過去完了を2つ以上使う。聞き手は初めて会うインドのビジネスパートナー。",
  taskEn:"Tell your story as a timeline with at least four events to a new business partner in India. Use the present perfect continuous at least three times and the past perfect at least twice. Speak for two and a half minutes.",
  qa:[
   {q:"How long have you been running your clinic?",a:"I have been running it since October 2018.",ja:"質問：院を営んでどのくらいですか？／答え：2018年10月から営んでいます。"},
   {q:"What did you do before you opened your clinic?",a:"I had worked as an athletic trainer for sports teams.",ja:"質問：院を開く前は何をしていましたか？／答え：スポーツチームのアスレティックトレーナーとして働いていました。"},
   {q:"Why have you been visiting India?",a:"Because I work with partners there. I help hotels and clinics welcome guests with omotenashi.",ja:"質問：なぜインドを訪れているのですか？／答え：現地のパートナーと仕事をしているからです。ホテルやクリニックがおもてなしでお客様を迎えるお手伝いをしています。"}],
  check:["現在完了進行形（have been …ing）を3つ以上使えたか","過去完了（had ＋ 過去分詞）で「もっと前」を言えたか","出来事ごとに「何を学んだか・どうつながったか」を言えたか","最後に「今」につなげて終われたか","2分30秒（約265語）で話せたか"],
  slide:"横線1本に「Trainer → 2018 Clinic → System → India」を左から置きます。話している出来事だけ色を変えます。"},

 {week:21, level:"B1", length:"2分30秒", title:"「もし〜なら」で提案する",
  skill:"仮定法過去（If we worked together, we could…）を使って、相手が想像しやすい提案ができる。",
  lesson:[
   "今週は「提案」のプレゼンです。提案は、相手に「もしそうなったら」を想像してもらうことが大切です。仮定法過去を使うと、If we worked together, we could…（もし一緒に仕事をしたら、…できるでしょう）のように、まだ起きていない未来をやわらかく描けます。",
   "提案の組み立ては「今の困りごと→もしこうしたら→得られること→次の一歩」です。いきなり「買ってください」と言うのではなく、まず相手の困りごとを言葉にして、「わかってくれている」と感じてもらいましょう。",
   "仮定法は押しつけない言い方なので、ていねいに聞こえます。It would be great if…（…ならうれしいです）、What if we tried…?（…してみたらどうでしょう）なども使えます。最後は、相手が今日決められる小さな一歩（短い打ち合わせなど）で終わると、話が前に進みます。",
   "スライドは「今」と「もしも」を左右に並べると、違いがひと目でわかります。左に今の困りごと、右に一緒にやった場合の姿を、3行ずつ書きましょう。"],
  structure:[{en:"Opening",ja:"あいさつ"},{en:"The current problem",ja:"今の困りごと"},{en:"What if…",ja:"もしこうしたら"},{en:"Benefits",ja:"得られること"},{en:"Next step",ja:"次の一歩"}],
  phrases:[
   {en:"I have a proposal for you today.",ja:"今日はご提案があります。",note:"提案のプレゼンの導入。"},
   {en:"Many hotels have the same problem.",ja:"多くのホテルが同じ困りごとをかかえています。",note:"まず困りごとを言う。"},
   {en:"If we worked together, we could welcome more Japanese guests.",ja:"もし一緒に仕事をしたら、もっと多くの日本人のお客様をお迎えできるでしょう。",note:"If ＋ 過去形, could ＋ 原形。"},
   {en:"If your staff knew a few Japanese customs, guests would feel at home.",ja:"スタッフが日本の習慣をいくつか知っていたら、お客様はくつろげるでしょう。",note:"would ＝〜だろう。"},
   {en:"Imagine if every guest left with a smile.",ja:"お客様みんなが笑顔で帰る様子を想像してください。",note:"聞き手に想像してもらう。"},
   {en:"What if we tried a short training first?",ja:"まず短い研修を試してみたらどうでしょう？",note:"やわらかい提案。"},
   {en:"It would be great if we could start next month.",ja:"来月から始められたら、うれしいです。",note:"ていねいな希望。"},
   {en:"If I were you, I would start with the front desk.",ja:"私があなたなら、フロントから始めます。",note:"If I were you でアドバイス。"},
   {en:"The first step is small and easy.",ja:"最初の一歩は小さくて簡単です。",note:"相手の負担を軽く見せる。"},
   {en:"Could we set up a short meeting next week?",ja:"来週、短い打ち合わせを設けられますか？",note:"次の一歩で終わる。"}],
  model:{title:"インドのホテルへのおもてなしの提案", time:"2分30秒", note:"提案の中身（研修の長さなど）は例です。実際の内容に合わせて入れかえましょう。",
   lines:[
    {en:"Good morning, everyone. Thank you for meeting me today. I have a proposal for you.",ja:"皆さん、おはようございます。今日はお会いいただき、ありがとうございます。ご提案があります。"},
    {en:"First, let me talk about a common problem.",ja:"まず、よくある困りごとについてお話しします。"},
    {en:"Many hotels in India want to welcome Japanese guests, and Indian guests who love Japan.",ja:"インドの多くのホテルが、日本人のお客様や、日本好きのインドのお客様をお迎えしたいと考えています。"},
    {en:"But Japanese guests often feel shy, and they do not always say what they need.",ja:"でも、日本人のお客様は遠慮しがちで、必要なことをいつも口に出すとは限りません。"},
    {en:"So the staff work hard, but the guest is still not fully happy.",ja:"そのため、スタッフはがんばっているのに、お客様はまだ十分に満足していないのです。"},
    {en:"This is a small gap, but guests feel it.",ja:"小さなずれですが、お客様はそれを感じます。"},
    {en:"Now, imagine a different picture.",ja:"では、ちがう姿を想像してみてください。"},
    {en:"If your staff knew a few Japanese customs, guests would feel at home from the first minute.",ja:"スタッフが日本の習慣をいくつか知っていたら、お客様は最初の1分からくつろげるでしょう。"},
    {en:"If they noticed small signs, they could help before the guest asks.",ja:"小さなサインに気づけたら、お客様が頼む前に手助けできるでしょう。"},
    {en:"This is omotenashi. I practice it every day at my clinic in Japan.",ja:"これがおもてなしです。私は日本の院で毎日実践しています。"},
    {en:"At the clinic, we notice when a patient looks tired or worried, and we speak to them first.",ja:"院では、患者さんが疲れていたり不安そうだったりすると気づいて、こちらから声をかけます。"},
    {en:"If we worked together, we could build this into your daily service.",ja:"もし一緒に仕事をしたら、これを毎日のサービスの中に組み込めるでしょう。"},
    {en:"What would you get? First, guests would feel cared for, so they would come back.",ja:"何が得られるでしょうか。1つめに、お客様は大切にされていると感じるので、また来てくれるでしょう。"},
    {en:"Second, they would tell their friends, and your hotel would be known for real Japanese hospitality.",ja:"2つめに、お客様が友達に話し、ホテルは本物の日本のおもてなしで知られるようになるでしょう。"},
    {en:"Third, your staff would feel proud of their work.",ja:"3つめに、スタッフが自分の仕事に誇りを持てるでしょう。"},
    {en:"Happy staff give better service, so this helps the guests too.",ja:"楽しく働くスタッフは、よりよいサービスをするので、お客様のためにもなります。"},
    {en:"Imagine if every guest left with a smile and a plan to come back.",ja:"お客様みんなが、笑顔で、また来る予定を立てて帰る様子を想像してください。"},
    {en:"So, what if we tried a short training first? If I were you, I would start with the front desk.",ja:"そこで、まず短い研修を試してみてはどうでしょう？私があなたなら、フロントから始めます。"},
    {en:"The first step is small and easy. It would be great if we could start next month.",ja:"最初の一歩は小さくて簡単です。来月から始められたら、うれしいです。"},
    {en:"Could we set up a short meeting next week to talk about the details?",ja:"来週、くわしいことを話す短い打ち合わせを設けられますか？"},
    {en:"Thank you for listening. I look forward to working with you.",ja:"ご清聴ありがとうございました。ご一緒できるのを楽しみにしています。"}]},
  task:"インドのホテルかクリニックに、おもてなしの研修を提案する。仮定法過去を4つ以上使い、最後は次の一歩（打ち合わせの約束）で終わる。2分30秒。",
  taskEn:"Make a proposal for omotenashi training to a hotel or clinic in India. Use the second conditional at least four times, and end with a clear next step, such as a meeting. Speak for two and a half minutes.",
  qa:[
   {q:"What would happen if we didn't change anything?",a:"Guests would still come, but many would not come back. That would be a lost chance.",ja:"質問：何も変えなかったらどうなりますか？／答え：お客様は来るでしょうが、多くはもどって来ないでしょう。それはもったいないことです。"},
   {q:"If we started, who should join first?",a:"If I were you, I would start with the front desk team, because they meet every guest first.",ja:"質問：始めるとしたら、誰から参加すべきですか？／答え：私なら、フロントのチームから始めます。すべてのお客様に最初に会うからです。"}],
  check:["仮定法過去（If ＋ 過去形, would / could ＋ 原形）を4つ以上使えたか","「困りごと→もしも→得られること→次の一歩」の順になっていたか","相手の困りごとを先に言葉にできたか","最後に小さな次の一歩を提案できたか","2分30秒（約280語）で話せたか"],
  slide:"左に「Now」、右に「If we worked together」と見出しをつけ、それぞれ3行で書きます。右側だけ明るい色にします。"},

 {week:22, level:"B1", length:"2分30秒", title:"ふりかえりと学びを語る",
  skill:"I wish / If I had… / What I learned is… を使って、正直なふりかえりと、そこからの学びを語れる。",
  lesson:[
   "今週は、ふりかえりのプレゼンです。うまくいったことだけでなく、「もっとこうすればよかった」を正直に話せる人は、聞き手から信頼されます。大事なのは、反省で終わらず、学びと次の行動につなげることです。",
   "使う形は3つです。今の残念な気持ちは I wish I could…（…できたらいいのに）。過去の「もしも」は If I had known…, I would have…（もし知っていたら、…していたでしょう）。学びのまとめは What I learned is that…（私が学んだのは…です）。What で始める文は、結論をはっきり伝えられます。",
   "組み立ては「何をしたか→うまくいったこと→もっとこうすればよかったこと→学び→次にすること」です。うまくいったことを先に言うと、聞き手は安心してあとの反省を聞けます。最後は前向きな一言で終わりましょう。",
   "スライドは「Good / Better / Next」の3列にすると、ふりかえりがひと目でわかります。各列は2行まで。くわしい気持ちは、話して伝えます。"],
  structure:[{en:"Opening",ja:"あいさつ"},{en:"What I did",ja:"何をしたか"},{en:"What went well",ja:"うまくいったこと"},{en:"What I wish",ja:"こうすればよかったこと"},{en:"What I learned / Next",ja:"学びと次の一歩"}],
  phrases:[
   {en:"Today, I'd like to look back on my work.",ja:"今日は、私の仕事をふりかえりたいと思います。",note:"ふりかえりの導入。"},
   {en:"Let me start with what went well.",ja:"うまくいったことから始めます。",note:"よいことを先に。"},
   {en:"I wish I could speak English more freely.",ja:"もっと自由に英語が話せたらいいのに。",note:"今の残念な気持ち。"},
   {en:"I wish I had started earlier.",ja:"もっと早く始めていたらよかった。",note:"過去への残念な気持ちは had ＋ 過去分詞。"},
   {en:"If I had known this, I would have shared the system sooner.",ja:"これを知っていたら、もっと早くシステムを共有していたでしょう。",note:"仮定法過去完了。"},
   {en:"What I learned is that small steps matter.",ja:"私が学んだのは、小さな一歩が大切だということです。",note:"学びを一言で。"},
   {en:"Looking back, I'm glad that I kept going.",ja:"ふりかえると、続けてよかったと思います。",note:"前向きな気持ち。"},
   {en:"To be honest, it was not easy.",ja:"正直に言うと、簡単ではありませんでした。",note:"正直さを伝える前置き。"},
   {en:"Next time, I will …",ja:"次は、…します。",note:"次の行動で終わる。"},
   {en:"It's time to take the next step.",ja:"次の一歩をふみ出す時です。",note:"It's time to ＋ 原形。"}],
  model:{title:"仕事と英語のふりかえり", time:"2分30秒", note:"ふりかえりの中身（できなかったこと・気づき）は例です。自分の経験に入れかえましょう。",
   lines:[
    {en:"Hello, everyone. Today, I'd like to look back on my work and my English.",ja:"皆さん、こんにちは。今日は、私の仕事と英語をふりかえりたいと思います。"},
    {en:"First, what I did. I have been running my clinic in Ozu since 2018.",ja:"まず、何をしてきたか。2018年から大洲で院を営んでいます。"},
    {en:"I also built a booking and customer system, and I have been visiting India for my work.",ja:"予約と顧客管理のシステムも作り、仕事でインドを訪れています。"},
    {en:"Let me start with what went well.",ja:"うまくいったことから始めます。"},
    {en:"I kept checking our sales, visits and return rate every day. This habit became a system that partner clinics now use.",ja:"毎日、売上・来院数・再来院率を確かめ続けました。この習慣が、今は提携院が使うシステムになりました。"},
    {en:"I also kept one rule: give my best to the person in front of me.",ja:"1つの決まりも守り続けました。目の前の人に全力を尽くすことです。"},
    {en:"Now, what I wish I had done better.",ja:"次に、もっとうまくできたらよかったことです。"},
    {en:"To be honest, my first meetings in India were not easy.",ja:"正直に言うと、インドでの最初の打ち合わせは簡単ではありませんでした。"},
    {en:"I prepared what to say, but I could not answer questions well.",ja:"話すことは準備していましたが、質問にうまく答えられませんでした。"},
    {en:"I wish I could speak English more freely. I often knew what to say in Japanese, but not in English.",ja:"もっと自由に英語が話せたらいいのに、と思います。日本語なら言えることが、英語では言えないことがよくありました。"},
    {en:"I wish I had started studying English earlier.",ja:"もっと早く英語の勉強を始めていたらよかったです。"},
    {en:"If I had prepared simple slides, my partners would have understood my ideas more easily.",ja:"簡単なスライドを用意していたら、パートナーは私の考えをもっと楽に理解できたでしょう。"},
    {en:"I also wish I had asked more questions, because questions help people understand each other.",ja:"もっと質問をすればよかったとも思います。質問は、おたがいをわかり合う助けになるからです。"},
    {en:"So, what did I learn?",ja:"では、何を学んだのでしょうか。"},
    {en:"What I learned is that small steps matter, at the clinic and in English.",ja:"私が学んだのは、院でも英語でも、小さな一歩が大切だということです。"},
    {en:"A few minutes with the numbers every day changed my clinic. A few hours of English every day can change my work in India.",ja:"毎日数分数字を見ることが、私の院を変えました。毎日数時間の英語が、インドでの仕事を変えられるはずです。"},
    {en:"What I also learned is that people care more about your heart than your grammar.",ja:"もう1つ学んだのは、人は文法よりも心を見ているということです。"},
    {en:"Next time, I will bring clear slides and ask more questions.",ja:"次は、わかりやすいスライドを持って行き、もっと質問をします。"},
    {en:"I will also practice my presentations every week, and record them to check my timing.",ja:"また、毎週プレゼンを練習し、録音して時間を確かめます。"},
    {en:"Looking back, I'm glad that I kept going. It's time to take the next step.",ja:"ふりかえると、続けてよかったと思います。次の一歩をふみ出す時です。"},
    {en:"Thank you for listening. I hope my story helps you look back on your own work.",ja:"ご清聴ありがとうございました。私の話が、皆さんが自分の仕事をふりかえるきっかけになればうれしいです。"}]},
  task:"この半年の自分の仕事か英語の勉強を、「うまくいったこと→こうすればよかったこと→学び→次」の順に2分30秒でふりかえる。I wish と If I had… と What I learned is… を必ず使う。",
  taskEn:"Look back on your work or English study over the last six months. Talk about what went well, what you wish you had done, what you learned, and your next step. Use I wish, If I had and What I learned is. Speak for two and a half minutes.",
  qa:[
   {q:"What would you do differently if you started again?",a:"If I started again, I would study English earlier and prepare simple slides.",ja:"質問：もう一度始めるとしたら、何を変えますか？／答え：もう一度始めるなら、もっと早く英語を勉強して、簡単なスライドを用意します。"},
   {q:"What is the most important lesson for you?",a:"What I learned is that small steps every day make a big difference.",ja:"質問：一番大切な学びは何ですか？／答え：毎日の小さな一歩が大きな違いを生む、ということです。"}],
  check:["I wish ＋ 過去形 と I wish ＋ had ＋ 過去分詞 を使い分けられたか","If I had …, I would have … の形を言えたか","What I learned is that … で学びをはっきり言えたか","うまくいったことを先に話し、最後は前向きに終われたか","2分30秒（約295語）で話せたか"],
  slide:"「Good / Better / Next」の3列で、各列2行まで。Next の列だけ色を変えて、前向きな終わりを見せます。"},

 {week:23, level:"B1", length:"2分30秒", title:"チームを紹介し、役割を伝える",
  skill:"使役動詞（have / let / get / make）を使って、チームの役割と仕事の進め方を説明できる。",
  lesson:[
   "今週は、自分だけでなく「チーム」を紹介する練習です。聞き手は、一人の力より、チームでどう動いているかを知りたいものです。役割をはっきり伝えると、「この人たちなら任せられる」と感じてもらえます。",
   "使役動詞は「人に〜してもらう・させる」を表します。I have my staff check the notes.（スタッフにメモを確かめてもらいます）、We let patients choose the time.（患者さんに時間を選んでもらいます）、I get my team to share ideas.（チームに考えを出してもらいます）。make は「（強く）させる」なので、プレゼンでは使い方に気をつけ、物が主語の This makes patients feel safe.（これで患者さんは安心します）のような形が使いやすいです。",
   "チームの紹介は「全体→役割→進め方→大切にしていること」の順にします。一人ずつの説明は短くし、「誰が何をするか」がわかれば十分です。最後に、チームで大切にしている考えを1つ言うと、話がまとまります。",
   "スライドは、真ん中に院、まわりに役割を丸で並べる図がわかりやすいです。顔写真を使うときは、本人の許可を取りましょう。"],
  structure:[{en:"Opening",ja:"あいさつ"},{en:"The team",ja:"チームの全体"},{en:"Roles",ja:"役割"},{en:"How we work",ja:"仕事の進め方"},{en:"What we value",ja:"大切にしていること"}],
  phrases:[
   {en:"Let me introduce my team.",ja:"私のチームをご紹介します。",note:"チーム紹介の導入。"},
   {en:"Each member has a clear role.",ja:"メンバーそれぞれに、はっきりした役割があります。",note:"役割の話に入る前に。"},
   {en:"I have my staff check the notes before each treatment.",ja:"施術の前に、スタッフにメモを確かめてもらいます。",note:"have ＋ 人 ＋ 原形。"},
   {en:"We let patients choose the time that suits them.",ja:"患者さんには、都合のよい時間を選んでもらっています。",note:"let ＋ 人 ＋ 原形 ＝自由にさせる。"},
   {en:"I get my team to share ideas at our weekly meeting.",ja:"週1回の打ち合わせで、チームに考えを出してもらいます。",note:"get ＋ 人 ＋ to ＋ 原形。"},
   {en:"This makes patients feel safe.",ja:"これで、患者さんは安心します。",note:"物が主語の make。"},
   {en:"I'm responsible for … , and our staff are responsible for …",ja:"私は…を担当し、スタッフは…を担当しています。",note:"担当を言う形。"},
   {en:"We work as one team, not as individuals.",ja:"私たちは、個人ではなく1つのチームとして働いています。",note:"チームらしさを伝える。"},
   {en:"I had the system set up so that everyone can see the numbers.",ja:"みんなが数字を見られるように、システムを整えてもらいました。",note:"have ＋ 物 ＋ 過去分詞。"},
   {en:"What we value most is …",ja:"私たちが一番大切にしているのは…です。",note:"結論の一言。"}],
  model:{title:"私たちのチームと役割", time:"2分30秒", note:"スタッフの役割や打ち合わせの回数は例です。自分のチームに合わせて入れかえましょう。",
   lines:[
    {en:"Good afternoon, everyone. Today, let me introduce my team at the clinic.",ja:"皆さん、こんにちは。今日は、院のチームをご紹介します。"},
    {en:"We are a small team. Four staff members work with me, and each member has a clear role.",ja:"私たちは小さなチームです。4人のスタッフが私と働いていて、それぞれにはっきりした役割があります。"},
    {en:"First, my own role. I'm responsible for treatments, staff training and clinic management.",ja:"まず、私の役割です。施術、スタッフの教育、院の経営を担当しています。"},
    {en:"I also check our sales, visits and return rate every day.",ja:"毎日、売上・来院数・再来院率も確かめています。"},
    {en:"Next, our staff. Some members work at the reception, and some work in the treatment rooms.",ja:"次に、スタッフです。受付で働くメンバーと、施術室で働くメンバーがいます。"},
    {en:"The reception team welcome patients and manage bookings. They are the first face of our clinic.",ja:"受付のチームは、患者さんをお迎えし、予約を管理します。院の最初の顔です。"},
    {en:"The treatment team support patients during their care.",ja:"施術のチームは、ケアの間、患者さんを支えます。"},
    {en:"They also give simple advice for home, so patients can keep getting better.",ja:"家でできる簡単なアドバイスもして、患者さんがよくなり続けられるようにします。"},
    {en:"Now, how do we work together? Here are four simple rules.",ja:"では、どのように一緒に働いているでしょうか。4つの簡単な決まりがあります。"},
    {en:"First, I have my staff check the notes before each treatment.",ja:"1つめに、施術の前に、スタッフにメモを確かめてもらいます。"},
    {en:"These notes tell us what the patient said last time. This makes patients feel remembered and safe.",ja:"メモには、患者さんが前回話したことが書いてあります。これで、患者さんは覚えてもらえていると感じ、安心します。"},
    {en:"Second, we let patients choose the time that suits them, and we let them ask any question.",ja:"2つめに、患者さんには都合のよい時間を選んでもらい、どんな質問もしてもらいます。"},
    {en:"Third, I get my team to share ideas at our weekly meeting. Good ideas often come from the reception.",ja:"3つめに、週1回の打ち合わせで、チームに考えを出してもらいます。よい考えは受付から出ることがよくあります。"},
    {en:"When people share ideas, they feel the clinic is their own place too.",ja:"考えを出し合うと、みんなが院を自分の場所だと感じられます。"},
    {en:"Fourth, I had our system set up so that everyone can see the numbers of the day.",ja:"4つめに、みんながその日の数字を見られるように、システムを整えました。"},
    {en:"When the staff see the numbers, they understand why their work matters.",ja:"スタッフは数字を見ると、自分の仕事がなぜ大切かがわかります。"},
    {en:"We do the same in our partner clinics. I help the owners have their staff share the numbers too.",ja:"提携院でも同じことをしています。院長が、スタッフにも数字を共有してもらえるようにお手伝いしています。"},
    {en:"We work as one team, not as individuals.",ja:"私たちは、個人ではなく1つのチームとして働いています。"},
    {en:"When one member is busy, another member helps without being asked. That is our kind of omotenashi.",ja:"誰かが忙しいときは、頼まれなくてもほかのメンバーが手伝います。それが私たちなりのおもてなしです。"},
    {en:"What we value most is simple: give our best to the person in front of us.",ja:"私たちが一番大切にしていることは簡単です。目の前の人に全力を尽くすことです。"},
    {en:"Thank you for listening. I'm happy to answer any questions about our team and how we work.",ja:"ご清聴ありがとうございました。チームと仕事の進め方についてのご質問に喜んでお答えします。"}]},
  task:"自分のチーム（院・提携院・インドのパートナーのどれか）を、役割と仕事の進め方がわかるように2分30秒で紹介する。have / let / get を全部使う。",
  taskEn:"Introduce your team, such as your clinic staff, so the audience understands each role and how you work together. Use have, let and get as causative verbs. Speak for two and a half minutes.",
  qa:[
   {q:"How do you train new staff?",a:"I have them watch experienced staff first. Then I let them try with my support.",ja:"質問：新しいスタッフはどう育てていますか？／答え：まず先輩の仕事を見てもらいます。それから、私が支えながらやってもらいます。"},
   {q:"Who decides the treatment plan?",a:"I'm responsible for the plan, but I get my team to share their ideas too.",ja:"質問：施術の計画は誰が決めますか？／答え：計画は私が担当していますが、チームにも考えを出してもらっています。"}],
  check:["have / let / get ＋ 人 ＋ 動詞 の形を正しく使えたか（to が要るのは get だけ）","「全体→役割→進め方→大切にしていること」の順で話せたか","一人ずつの説明を短くできたか","make を強すぎない形（This makes …）で使えたか","2分30秒（約310語）で話せたか"],
  slide:"真ん中に「Our clinic」、まわりに Reception / Treatment / Management の丸を3つ置きます。丸の中は1語だけにします。"},

 {week:24, level:"B1", length:"2分30秒", title:"お客様の声・調査の結果を伝える",
  skill:"報告の言い方（Patients told us that… / Many said… / We asked if…）を使って、お客様の声と調査の結果を正確に伝えられる。",
  lesson:[
   "今週は、お客様の声や調査の結果を伝える練習です。自分の考えだけでなく「お客様がこう言っている」と伝えると、話の説得力がぐっと上がります。そのとき使うのが、報告の言い方です。",
   "人が言ったことは said that / told us that で伝えます。Patients told us that they wanted more time to talk.（患者さんは、もっと話す時間がほしいと言いました）。質問したことは asked if / asked what で伝えます。We asked patients if they would recommend us.（おすすめしたいかどうかを聞きました）。言ったときより前のことなので、動詞は1つ過去に下げるのが基本です。",
   "調査の結果は「何を、誰に、どう聞いたか→わかったこと→声の例→次にすること」の順に話します。数字だけでなく、お客様の言葉を1つか2つそえると、聞き手の心に残ります。お客様の声を使うときは、名前を出さず、本人の許可を取ることも大切です。",
   "スライドは、大きな数字1つと、短い声の引用を1つ並べます。数字は「10人中8人」のように、わかりやすい形にしましょう。"],
  structure:[{en:"Opening",ja:"あいさつ"},{en:"The survey",ja:"調査の方法"},{en:"Results",ja:"結果"},{en:"Voices",ja:"お客様の声"},{en:"Next actions",ja:"次にすること"}],
  phrases:[
   {en:"We asked our patients a few simple questions.",ja:"患者さんに、いくつか簡単な質問をしました。",note:"調査の説明の始め。"},
   {en:"We asked them if they would recommend us to a friend.",ja:"友達におすすめしたいかどうかを聞きました。",note:"asked if ＝〜かどうか聞いた。"},
   {en:"We also asked what they liked most.",ja:"一番よかったことも聞きました。",note:"asked what ＋ 主語 ＋ 動詞。"},
   {en:"Eight out of ten patients said that they would.",ja:"10人中8人が、おすすめしたいと答えました。",note:"数字はわかりやすい形で。"},
   {en:"Patients told us that they wanted more time to talk.",ja:"患者さんは、もっと話す時間がほしいと言いました。",note:"told us that ＋ 過去形。"},
   {en:"One patient said that she felt listened to.",ja:"ある患者さんは、話を聞いてもらえたと感じたと言いました。",note:"声の例を1つ。"},
   {en:"Many people mentioned the reception staff.",ja:"多くの方が、受付のスタッフについてふれていました。",note:"mention ＝ふれる。"},
   {en:"According to the survey, …",ja:"調査によると、…",note:"結果を伝える前置き。"},
   {en:"These results show that …",ja:"これらの結果は…を示しています。",note:"意味をまとめる。"},
   {en:"Based on this feedback, we decided to …",ja:"この声をもとに、…することにしました。",note:"次の行動につなげる。"}],
  model:{title:"患者さんアンケートの結果", time:"2分30秒", note:"数字とお客様の声は練習用の例です。実際の調査の数字と声に入れかえましょう。",
   lines:[
    {en:"Good morning, everyone. Today, I'd like to share what our patients told us.",ja:"皆さん、おはようございます。今日は、患者さんが私たちに伝えてくれたことをお話しします。"},
    {en:"Last month, we asked our patients a few simple questions on a short paper survey at the reception.",ja:"先月、受付で、短い紙のアンケートで、患者さんにいくつか簡単な質問をしました。"},
    {en:"Fifty patients answered. We did not ask for their names.",ja:"50人の患者さんが答えてくれました。名前は聞きませんでした。"},
    {en:"We wanted honest answers, so the survey was short and easy.",ja:"正直な答えがほしかったので、アンケートは短く簡単にしました。"},
    {en:"First, we asked them if they would recommend our clinic to a friend.",ja:"まず、友達に院をおすすめしたいかどうかを聞きました。"},
    {en:"According to the survey, forty patients said that they would. That's eight out of ten.",ja:"調査によると、40人がおすすめしたいと答えました。10人中8人です。"},
    {en:"Next, we asked what they liked most about our clinic.",ja:"次に、院の何が一番よかったかを聞きました。"},
    {en:"Many people mentioned the reception staff. They said that the staff remembered them.",ja:"多くの方が受付のスタッフについてふれていました。スタッフが自分のことを覚えていてくれた、と言っていました。"},
    {en:"One patient said that she felt listened to for the first time.",ja:"ある患者さんは、初めて話を聞いてもらえたと感じた、と言いました。"},
    {en:"When I read this comment to my team, everyone was very happy.",ja:"この声をチームに読み上げると、みんなとても喜びました。"},
    {en:"Another patient told us that the advice for home was very useful.",ja:"別の患者さんは、家でできるアドバイスがとても役に立った、と言いました。"},
    {en:"We also asked if there was anything we could do better.",ja:"もっとよくできることがあるかどうかも聞きました。"},
    {en:"Some patients told us that they wanted more time to talk about their pain and their daily life.",ja:"何人かの患者さんは、痛みや毎日の生活について、もっと話す時間がほしいと言いました。"},
    {en:"Others said that booking by phone was sometimes difficult.",ja:"ほかの方は、電話での予約がときどきむずかしいと言いました。"},
    {en:"Some said that they could not call during work hours.",ja:"仕事の時間中は電話できない、と言った方もいました。"},
    {en:"These results show that our care for each person is working, and that our staff make a real difference.",ja:"これらの結果は、一人ひとりへの心づかいがうまくいっていて、スタッフが大きな違いを生んでいることを示しています。"},
    {en:"They also show that we need to give more time and make booking easier.",ja:"同時に、もっと時間をとり、予約をもっと簡単にする必要があることも示しています。"},
    {en:"Based on this feedback, we decided to do two things right away.",ja:"この声をもとに、すぐに2つのことをすることにしました。"},
    {en:"First, I asked my staff to save five minutes at the end of each visit for questions.",ja:"1つめに、来院の最後に質問のための5分をとるよう、スタッフに頼みました。"},
    {en:"Second, we will let patients book their next visit at the reception before they leave. This way, they will not need to call us later.",ja:"2つめに、帰る前に受付で次の予約を入れてもらえるようにします。こうすれば、あとで電話をする必要がありません。"},
    {en:"I believe this kind of survey can help any clinic, hotel or restaurant, because it costs very little.",ja:"このようなアンケートは、費用がほとんどかからないので、どんな院やホテル、レストランにも役立つと思います。"},
    {en:"Your guests will tell you what they need, if you ask them. So please ask, and really listen to the answers. Thank you for listening.",ja:"たずねれば、お客様は必要なことを教えてくれます。ですから、ぜひたずねて、答えにしっかり耳をかたむけてください。ご清聴ありがとうございました。"}]},
  task:"例の数字とお客様の声を使って、アンケートの結果を2分30秒で報告する。said that / told us that / asked if を全部使う。聞き手は提携院の院長たち、またはインドのホテルの方。",
  taskEn:"Report the results of a customer survey using example numbers and example comments. Use said that, told us that and asked if. Speak to partner clinic owners or a hotel team in India for two and a half minutes.",
  qa:[
   {q:"How did you ask the patients?",a:"We asked them on a short paper survey. We did not ask for their names, so they could answer freely.",ja:"質問：患者さんにどうやって聞きましたか？／答え：短い紙のアンケートで聞きました。名前を聞かなかったので、自由に答えてもらえました。"},
   {q:"What was the most surprising answer?",a:"Some patients told us that they wanted more time to talk. I thought we already listened enough.",ja:"質問：一番意外だった答えは何ですか？／答え：何人かの患者さんが、もっと話す時間がほしいと言ったことです。十分聞けていると思っていました。"},
   {q:"Will you do the survey again?",a:"Yes. We plan to ask the same questions again and compare the results.",ja:"質問：またアンケートをしますか？／答え：はい。同じ質問をもう一度して、結果を比べる予定です。"}],
  check:["said that / told us that / asked if を正しく使えたか","言った内容の動詞を過去に下げられたか（want → wanted）","「方法→結果→声→次にすること」の順で話せたか","例の数字とお客様の声が、例であることを伝えたか","2分30秒（約325語）で話せたか"],
  slide:"左に大きく「8 out of 10」、右に短い声を1つ（“I felt listened to.”）。数字は1つだけにします。"},

 {week:25, level:"B1", length:"3分", title:"プレゼンでよく使う句動詞",
  skill:"go over / move on / point out / sum up / come up with / look into などの句動詞で、プレゼンの進行を自然に案内できる。",
  lesson:[
   "今週は、プレゼンの「進め方」を案内する言葉を学びます。英語のプレゼンでは、句動詞（動詞＋小さな言葉）がとてもよく使われます。Let's go over the plan.（計画を見ていきましょう）、Let's move on to the next point.（次の点に移りましょう）のように、短くて、話し言葉らしい言い方です。",
   "プレゼンの流れに合わせて句動詞を覚えると便利です。始めに go over（ざっと見る）、途中で move on（次へ進む）・point out（指摘する）、考えを出すときに come up with（思いつく）、調べるときに look into（調べる）、最後に sum up（まとめる）。この6つがあれば、話の「道案内」ができます。",
   "長いプレゼンでは、聞き手は「今どこにいるか」を見失いがちです。話の区切りごとに句動詞で合図を出し、ときどき「ここまでのまとめ」をはさむと、3分の話でも聞き手はついて来られます。",
   "スライドの1枚目に「今日の流れ（Agenda）」を3つ書いておき、話が進むたびに、そのスライドにもどる方法もあります。今どこかを色で見せると、さらにわかりやすくなります。"],
  structure:[{en:"Opening and agenda",ja:"あいさつと今日の流れ"},{en:"Where we are",ja:"今の状況"},{en:"Ideas",ja:"考えたこと"},{en:"Next steps",ja:"次にすること"},{en:"Summary",ja:"まとめ"}],
  phrases:[
   {en:"Let's go over today's plan.",ja:"今日の流れを見ていきましょう。",note:"go over ＝ざっと見る・確認する。"},
   {en:"Let's move on to the next point.",ja:"次の点に移りましょう。",note:"move on ＝次へ進む。"},
   {en:"I'd like to point out one thing here.",ja:"ここで1つ指摘したいことがあります。",note:"point out ＝指摘する。"},
   {en:"We came up with three ideas.",ja:"私たちは3つの案を考えました。",note:"come up with ＝思いつく。"},
   {en:"We will look into the cost next week.",ja:"来週、費用を調べます。",note:"look into ＝くわしく調べる。"},
   {en:"To sum up, …",ja:"まとめると、…",note:"sum up ＝まとめる。"},
   {en:"Let me go back to the first point.",ja:"最初の点にもどらせてください。",note:"go back to ＝もどる。"},
   {en:"We need to find out why.",ja:"理由を見つける必要があります。",note:"find out ＝わかる・見つけ出す。"},
   {en:"I'll follow up with an email.",ja:"あとでメールでご連絡します。",note:"follow up ＝あとで連絡する。"},
   {en:"Let's set up a time to talk again.",ja:"また話す時間を決めましょう。",note:"set up ＝準備する・設ける。"}],
  model:{title:"提携院との3か月の計画", time:"3分", note:"数字や計画の中身は練習用の例です。自分の数字と計画に入れかえましょう。",
   lines:[
    {en:"Good afternoon, everyone. Thank you for joining this meeting.",ja:"皆さん、こんにちは。この打ち合わせにご参加いただき、ありがとうございます。"},
    {en:"Today, I'll talk about our plan for the next three months. Let's go over today's plan first.",ja:"今日は、これからの3か月の計画についてお話しします。まず、今日の流れを見ていきましょう。"},
    {en:"I'll talk about three things: where we are now, the ideas we came up with, and our next steps.",ja:"3つのことをお話しします。今の状況、考えた案、そして次にすることです。"},
    {en:"First, where we are now. All of you use the same booking and customer system.",ja:"まず、今の状況です。皆さんは全員、同じ予約と顧客管理のシステムを使っています。"},
    {en:"So we can see the same numbers: sales, visits and return rate.",ja:"ですから、売上・来院数・再来院率という同じ数字を見ることができます。"},
    {en:"I'd like to point out one thing here. In two clinics, the return rate went down from 70 to 62 percent.",ja:"ここで1つ指摘したいことがあります。2つの院で、再来院率が70パーセントから62パーセントに下がりました。"},
    {en:"We need to find out why. The numbers tell us what happened, but not why.",ja:"理由を見つける必要があります。数字は何が起きたかは教えてくれますが、なぜかは教えてくれません。"},
    {en:"When we know the reason, we can choose the right action.",ja:"理由がわかれば、正しい行動を選べます。"},
    {en:"Now, let's move on to the next point: our ideas.",ja:"では、次の点、私たちの案に移りましょう。"},
    {en:"Last week, I talked with the owners, and we came up with three ideas.",ja:"先週、院長の皆さんと話し、3つの案を考えました。"},
    {en:"The first idea is to call patients who have not come back for a month.",ja:"1つめの案は、1か月来ていない患者さんにお電話することです。"},
    {en:"The second idea is to have the staff write a short note after each visit.",ja:"2つめの案は、来院のたびに、スタッフに短いメモを書いてもらうことです。"},
    {en:"The third idea is to explain the treatment plan clearly on the first visit.",ja:"3つめの案は、初回に施術の計画をわかりやすく説明することです。"},
    {en:"Let me go back to the first point for a moment. The clinics with good notes did not see a drop.",ja:"少しだけ最初の点にもどらせてください。メモをきちんと書いていた院では、下がっていませんでした。"},
    {en:"So I think the second idea is the most important, although all three are worth trying.",ja:"ですから、3つともためす価値はありますが、2つめの案が一番大切だと思います。"},
    {en:"Now, let's move on to our next steps.",ja:"では、次にすることに移りましょう。"},
    {en:"This month, we will set up a simple note form in the system, so the staff can write a note in one minute.",ja:"今月、スタッフが1分でメモを書けるように、システムの中に簡単なメモの書式を用意します。"},
    {en:"I will also look into the cost of phone calls and the staff time they take.",ja:"電話の費用と、それにかかるスタッフの時間も調べます。"},
    {en:"Next month, we will start the calls and the first-visit explanation in two clinics, so we can compare the results.",ja:"来月、2つの院で電話と初回の説明を始めて、結果を比べられるようにします。"},
    {en:"In the third month, we will check the numbers together and find out what worked.",ja:"3か月目に、一緒に数字を確かめ、何がうまくいったかを見つけます。"},
    {en:"To sum up, we found a problem, we came up with three ideas, and we will test them step by step.",ja:"まとめると、問題を見つけ、3つの案を考え、それを一歩ずつ試していきます。"},
    {en:"I'll follow up with an email today. Let's set up a time to talk again next month. Thank you.",ja:"今日、メールでご連絡します。来月また話す時間を決めましょう。ありがとうございました。"}]},
  task:"提携院か、インドのパートナーとの「これからの3か月の計画」を3分で話す。句動詞を6つ以上使い、話の区切りごとに進行の合図を入れる。",
  taskEn:"Present a three-month plan to partner clinics or partners in India. Use at least six phrasal verbs, such as go over, move on, point out, come up with, look into and sum up. Speak for three minutes.",
  qa:[
   {q:"Why did the return rate go down?",a:"We need to look into it more. But we pointed out one thing: the clinics with good notes did not see a drop.",ja:"質問：なぜ再来院率が下がったのですか？／答え：もっと調べる必要があります。ただ、メモをきちんと書いていた院では下がっていなかった、という点は指摘しました。"},
   {q:"Who came up with these ideas?",a:"We came up with them together. I talked with the owners last week.",ja:"質問：この案は誰が考えたのですか？／答え：一緒に考えました。先週、院長の皆さんと話しました。"},
   {q:"When will you send the details?",a:"I'll follow up with an email today.",ja:"質問：くわしいことはいつ送ってもらえますか？／答え：今日、メールでご連絡します。"}],
  check:["句動詞を6つ以上、正しい意味で使えたか","始めに go over で今日の流れを言えたか","話の区切りで move on の合図を出せたか","最後に sum up で3つの点をまとめられたか","3分（約345語）で話せたか"],
  slide:"1枚目に「Agenda：1 Where we are / 2 Ideas / 3 Next steps」。話が進むたびにもどり、今の項目だけ色を変えます。"},

 {week:26, level:"B1", length:"3分", title:"第2期の発表：3分「自分の事業」プレゼン",
  skill:"第2期で学んだ文法とつなぎの言葉を使って、自分の事業を3分で、筋道を立てて発表できる。",
  lesson:[
   "第2期のまとめの発表です。これまでの13週で、受動態・関係代名詞・分詞・接続詞・間接疑問・完了形・仮定法・使役・報告の言い方・句動詞を学びました。今週は、それを全部使って「自分の事業」を3分で発表します。新しいことは覚えず、今までの表現を組み合わせましょう。",
   "3分のプレゼンは、導入30秒・本論2分・結論30秒が目安です。導入で「今日は3つのことを話します」と予告し、本論は3つの柱（院・提携院への支援・インドとの仕事）に分けます。結論では3つを一言ずつまとめ、聞き手への提案や呼びかけで終わります。",
   "聞き手を意識することも忘れずに。最初に聞き手へ問いかけ、本論の途中で「ここまでで質問はありますか」と目を合わせ、最後に「もし一緒に仕事をしたら」と相手の未来を描きます。話しているのはあなたでも、主役は聞き手です。",
   "スライドは5枚までにしましょう。①題と名前、②今日の流れ、③〜④柱ごとに1枚ずつ（または写真）、⑤まとめと連絡先。文字は少なく、大きく。練習では必ず時間を計って録音し、3分を超えたら、文を削って短くします。"],
  structure:[{en:"Opening and question",ja:"あいさつと問いかけ"},{en:"Agenda",ja:"今日の流れ"},{en:"Pillar 1: The clinic",ja:"柱1：院"},{en:"Pillar 2: Supporting clinics",ja:"柱2：提携院への支援"},{en:"Pillar 3: Working with India",ja:"柱3：インドとの仕事"},{en:"Summary and proposal",ja:"まとめと提案"}],
  phrases:[
   {en:"Today, I'll talk about three parts of my work.",ja:"今日は、私の仕事の3つの部分についてお話しします。",note:"予告で数を言う。"},
   {en:"Could you tell me if you have ever visited Japan?",ja:"日本に行ったことがあるか教えていただけますか？",note:"導入の問いかけ（間接疑問）。"},
   {en:"My clinic was opened in October 2018.",ja:"私の院は2018年10月に開院しました。",note:"受動態（第14週）。"},
   {en:"I built a system which helps small clinics.",ja:"小さな院を助けるシステムを作りました。",note:"関係代名詞（第15週）。"},
   {en:"I have been visiting India regularly.",ja:"インドを定期的に訪れています。",note:"現在完了進行形（第20週）。"},
   {en:"Patients told us that they felt listened to.",ja:"患者さんは、話を聞いてもらえたと感じたと言いました。",note:"報告の言い方（第24週）。"},
   {en:"Let's move on to the third part.",ja:"3つめの部分に移りましょう。",note:"句動詞（第25週）。"},
   {en:"Although these look different, they share one idea.",ja:"これらは違って見えますが、1つの考えでつながっています。",note:"接続詞（第18週）。"},
   {en:"If we worked together, we could create something special.",ja:"もし一緒に仕事をしたら、特別なものを作れるでしょう。",note:"仮定法過去（第21週）。"},
   {en:"To sum up, …",ja:"まとめると、…",note:"結論の合図（第25週）。"}],
  model:{title:"私の事業", time:"3分", note:"お客様の声は例です。自分が実際に聞いた声に入れかえましょう。",
   lines:[
    {en:"Good morning, everyone. Before I start, could you tell me if you have ever visited Japan?",ja:"皆さん、おはようございます。始める前に、日本に行ったことがあるか教えていただけますか？"},
    {en:"Thank you. I see some hands. My name is Akihiro Iwata, and I come from Japan.",ja:"ありがとうございます。何人か手が挙がっていますね。岩田章弘です。日本から来ました。"},
    {en:"Today, I'll talk about three parts of my work: my clinic, my support for other clinics, and my work with India.",ja:"今日は、私の仕事の3つの部分についてお話しします。院、ほかの院への支援、そしてインドとの仕事です。"},
    {en:"First, my clinic. Aki Acupuncture and Judo Therapy Clinic was opened in October 2018 in Ozu, a small city in Ehime.",ja:"1つめは院です。あき鍼灸整骨院は、2018年10月に、愛媛県の小さな町、大洲で開院しました。"},
    {en:"Before that, I had worked as an athletic trainer for school, company and professional sports teams.",ja:"その前は、学校・実業団・プロのスポーツチームのアスレティックトレーナーとして働いていました。"},
    {en:"Now I run the clinic with four staff members. We offer acupuncture, injury care, posture care and postnatal care.",ja:"今は4人のスタッフと院を営んでいます。鍼灸、けがのケア、姿勢のケア、産後のケアをしています。"},
    {en:"What we value most is care for each person. Patients often tell us that they feel listened to.",ja:"私たちが一番大切にしているのは、一人ひとりへの心づかいです。患者さんからは、話を聞いてもらえたと感じる、とよく言われます。"},
    {en:"Let's move on to the second part: my support for other clinics.",ja:"2つめの部分、ほかの院への支援に移りましょう。"},
    {en:"I have been checking our sales, visits and return rate every day since we opened.",ja:"開院以来、売上・来院数・再来院率を毎日確かめ続けています。"},
    {en:"Because this habit helped my clinic so much, I built a booking and customer system which helps small clinics.",ja:"この習慣が院にとても役立ったので、小さな院を助ける予約と顧客管理のシステムを作りました。"},
    {en:"Today, it is used by our partner clinics, and I give them management advice, so they can grow step by step.",ja:"今は提携院で使われていて、一歩ずつ成長できるよう、私は経営のアドバイスをしています。"},
    {en:"So far, so good? Let me know if anything is unclear.",ja:"ここまで大丈夫ですか？わかりにくいところがあれば教えてください。"},
    {en:"Now, the third part: my work with India.",ja:"では、3つめの部分、インドとの仕事です。"},
    {en:"I have been visiting India regularly, and I work with partners there, so I understand both cultures a little better each time.",ja:"私はインドを定期的に訪れ、現地のパートナーと仕事をしているので、行くたびに2つの文化を少しずつ深く理解しています。"},
    {en:"I help hotels, restaurants and clinics welcome Japanese guests, and Indian guests who love Japan, with real omotenashi.",ja:"ホテルやレストラン、クリニックが、日本人のお客様や日本好きのインドのお客様を、本物のおもてなしで迎えるお手伝いをしています。"},
    {en:"I'm also the International Affairs Manager of Odani Sake Ten, my family's sake shop, which was founded in 1957.",ja:"また、1957年創業の家族の酒店、小谷酒店の国際担当もしています。"},
    {en:"Although these three parts look different, they share one idea: give your best to the person in front of you.",ja:"この3つは違って見えますが、1つの考えでつながっています。目の前の人に全力を尽くすことです。"},
    {en:"At the clinic, it is the patient. In my support work, it is the clinic owner. In India, it is the guest.",ja:"院では患者さん、支援の仕事では院長、インドではお客様がその人です。"},
    {en:"I learned this as a trainer, and I still practice it every day.",ja:"これはトレーナーのときに学び、今も毎日実践しています。"},
    {en:"To sum up, I care for people at my clinic, I help clinics grow with numbers, and I bring omotenashi to India.",ja:"まとめると、私は院で人を大切にし、数字で院の成長を助け、インドにおもてなしを届けています。"},
    {en:"If we worked together, we could create a place where every guest feels truly welcome, in Japan and in India.",ja:"もし一緒に仕事をしたら、日本でもインドでも、すべてのお客様が心から歓迎されていると感じる場所を作れるでしょう。"},
    {en:"Thank you very much for listening. I'd be happy to take your questions.",ja:"ご清聴、本当にありがとうございました。喜んでご質問をお受けします。"}]},
  task:"第2期のまとめとして、自分の事業を3分で発表する。導入で問いかけ、本論は3つの柱、結論で提案をする。第2期の文法を5つ以上使い、時間を計って録音する。聞き手はインドの企業の方々。",
  taskEn:"As the final task of Term 2, present your business in three minutes to a group of business people in India. Start with a question, give three main parts, and end with a proposal. Use at least five grammar points from weeks 14 to 25.",
  qa:[
   {q:"Which part of your work is the most important to you?",a:"They are all connected, but the clinic is the base. Everything I do started there.",ja:"質問：仕事の中で一番大切なのはどの部分ですか？／答え：すべてつながっていますが、院が土台です。すべてはそこから始まりました。"},
   {q:"How could we work together?",a:"If you welcome Japanese guests, I could train your staff in omotenashi. Could you tell me what kind of guests you have?",ja:"質問：どのように一緒に仕事ができますか？／答え：日本人のお客様をお迎えしているなら、スタッフにおもてなしの研修ができます。どんなお客様がいらっしゃるか教えていただけますか？"},
   {q:"Can other clinics in India use your system?",a:"That's a good question. It was made for clinics in Japan, so I'd need to look into it. I'll follow up with an email.",ja:"質問：インドのクリニックもシステムを使えますか？／答え：よいご質問です。日本の院のために作られたので、調べる必要があります。メールでご連絡します。"}],
  check:["導入30秒・本論2分・結論30秒のバランスで、3分におさまったか（約380語）","導入で問いかけと「3つの話」の予告ができたか","第2期の文法を5つ以上使えたか","本論の途中で聞き手に声をかけられたか","結論で3つをまとめ、提案で終われたか"],
  slide:"スライドは5枚まで。①題と名前 ②Agenda ③Clinic と System ④India ⑤「One idea: the person in front of you」と連絡先。"}
]);
